AND m.status = 1
AND s.status != 0

    AND s.user_id = #{scopedUserId}


    AND (u.username LIKE CONCAT('%', #{username}, '%')
        OR u.nickname LIKE CONCAT('%', #{username}, '%'))


    AND e.real_name LIKE CONCAT('%', #{expertName}, '%')


    AND s.session_no LIKE CONCAT('%', #{sessionNo}, '%')


    AND m.message_type = #{messageType}


    AND m.create_time >= #{startTime}


    AND m.create_time <= #{endTime}

mapper.select:
SELECT 
FROM `consult_message` m

WHERE m.session_id = #{sessionId}
  AND e.user_id = #{expertUserId}
  AND m.status = 1 AND s.status != 0
  AND m.id < #{beforeId}
  AND m.id > #{afterId}

    ORDER BY m.id ASC
    ORDER BY m.id DESC

LIMIT #{limit}

mapper.update:
UPDATE `consult_message` m
INNER JOIN `consult_session` s ON s.id = m.session_id
INNER JOIN `expert_profile` e ON e.id = s.expert_id
SET m.is_read = 1, m.read_time = NOW()
WHERE m.session_id = #{sessionId}
  AND e.user_id = #{expertUserId}
  AND m.receiver_id = #{expertUserId}
  AND m.is_read = 0 AND m.status = 1

UPDATE `consult_message` m
INNER JOIN `consult_session` s ON s.id = m.session_id
SET m.is_read = 1,
    m.read_time = NOW()
WHERE m.session_id = #{sessionId}
  AND s.user_id = #{userId}
  AND m.receiver_id = #{userId}
  AND m.is_read = 0
  AND m.status = 1
